<!-- eslint-disable vue/no-v-html -- the SVG is generated by our own code from palette colours, never from user input -->
<template>
    <span
        role="img"
        :aria-label="t(`settings.style.names.${styleId}`)"
        :data-testid="`style-icon-${styleId}`"
        class="style-icon"
        :style="{ width: `${size}px`, height: `${size}px` }"
        v-html="svg"
    />
</template>

<script setup lang="ts">
import { computed } from "vue";
import { useI18n } from "vue-i18n";
import type { Palette } from "@/theme/palettes";
import { styleIconSvg } from "@/theme/styleIcons";
import type { StyleId } from "@/theme/themeIds";

const props = defineProps<{
    styleId: StyleId;
    palette: Palette;
    size: number;
}>();

const { t } = useI18n();

const svg = computed(() => styleIconSvg(props.styleId, props.palette));
</script>

<style scoped>
.style-icon {
    display: block;
    flex-shrink: 0;
    overflow: hidden;
    border-radius: 24%;
}

.style-icon :deep(svg) {
    display: block;
    width: 100%;
    height: 100%;
}
</style>
